<?php /* Template Name: Account Settings */ if ( ! is_user_logged_in() ) { wp_safe_redirect( wp_login_url( get_permalink() ) ); exit; } $user = wp_get_current_user(); get_header(); ?><main id="primary" class="sd-main sd-settings-main"><div class="sd-container sd-content-wrap"><div class="sd-settings-layout"><aside class="sd-card sd-card-body sd-settings-nav"><a class="is-active" href="#profile"><?php esc_html_e( 'Profile', 'social-discovery' ); ?></a><a href="#password"><?php esc_html_e( 'Password', 'social-discovery' ); ?></a><a href="#privacy"><?php esc_html_e( 'Privacy', 'social-discovery' ); ?></a><a href="#onboarding"><?php esc_html_e( 'Onboarding', 'social-discovery' ); ?></a></aside><div class="sd-settings-content"><div class="sd-card sd-card-body" id="profile"><h1><?php esc_html_e( 'Account settings', 'social-discovery' ); ?></h1><?php if ( isset( $_GET['sd_profile'] ) ) : ?><div class="sd-auth-message sd-auth-message-success" role="status"><?php esc_html_e( 'Your settings were updated.', 'social-discovery' ); ?></div><?php endif; ?><?php get_template_part( 'template-parts/members/profile-settings', null, array( 'user' => $user ) ); ?></div><div class="sd-card sd-card-body" id="password"><h2><?php esc_html_e( 'Password', 'social-discovery' ); ?></h2><?php if ( function_exists( 'sd_core_password_update_handler' ) ) : ?><form class="sd-form-grid" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="sd_update_password"><?php wp_nonce_field( 'sd_account_password' ); ?><div class="sd-field"><label for="sd-account-pass1"><?php esc_html_e( 'New password', 'social-discovery' ); ?></label><input id="sd-account-pass1" type="password" name="pass1" minlength="8" autocomplete="new-password" required></div><div class="sd-field"><label for="sd-account-pass2"><?php esc_html_e( 'Confirm new password', 'social-discovery' ); ?></label><input id="sd-account-pass2" type="password" name="pass2" minlength="8" autocomplete="new-password" required></div><button class="sd-button sd-button-primary" type="submit"><?php esc_html_e( 'Update password', 'social-discovery' ); ?></button></form><?php endif; ?></div><div class="sd-card sd-card-body" id="privacy"><h2><?php esc_html_e( 'Privacy', 'social-discovery' ); ?></h2><?php if ( function_exists( 'sd_core_privacy_handler' ) ) : ?><form class="sd-form-grid" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="sd_save_privacy"><?php wp_nonce_field( 'sd_privacy' ); ?><?php $visibility = sd_core_profile_visibility( $user->ID ); ?><select name="profile_visibility"><option value="public" <?php selected( $visibility, 'public' ); ?>><?php esc_html_e( 'Public', 'social-discovery' ); ?></option><option value="members" <?php selected( $visibility, 'members' ); ?>><?php esc_html_e( 'Members only', 'social-discovery' ); ?></option><option value="private" <?php selected( $visibility, 'private' ); ?>><?php esc_html_e( 'Private', 'social-discovery' ); ?></option></select><button class="sd-button sd-button-primary" type="submit"><?php esc_html_e( 'Save privacy', 'social-discovery' ); ?></button></form><?php else : ?><p><?php esc_html_e( 'Privacy controls become available when Social Discovery Core is active.', 'social-discovery' ); ?></p><?php endif; ?></div><div class="sd-card sd-card-body" id="onboarding"><h2><?php esc_html_e( 'Onboarding', 'social-discovery' ); ?></h2><a class="sd-button sd-button-outline" href="<?php echo esc_url( sd_auth_url( 'onboarding', '/' ) ); ?>"><?php esc_html_e( 'Resume onboarding', 'social-discovery' ); ?></a><a class="sd-button sd-button-outline" href="<?php echo esc_url( sd_auth_logout_url() ); ?>"><?php esc_html_e( 'Log out', 'social-discovery' ); ?></a></div></div></div></div></main><?php get_footer(); ?>
